export const COMPANY_DIAGNOSIS_BRIEF="Analise o posicionamento, o público, a oferta e a identidade da minha empresa com base nas informações salvas. Indique prioridades práticas e perguntas para completar o diagnóstico. Separe fatos de hipóteses, sem inventar pesquisa de mercado.";

const activeStates=new Set(['queued','working','waiting_provider']);
const statuses={queued:'Na fila',working:'Analisando',waiting_provider:'Aguardando resposta',succeeded:'Concluído',failed:'Não concluído',blocked:'Precisa de ajuste',uncertain:'Precisa de conferência',canceled:'Cancelado'};
export function companyDiagnosisCard(state,{esc,formatTime}){
 const jobs=(state.jobs||[]).filter(j=>j.kind==='agent'&&j.payload?.agent==='strategy'&&j.payload?.purpose==='company_diagnosis').sort((a,b)=>(b.createdAt||b.updatedAt||0)-(a.createdAt||a.updatedAt||0));
 const last=jobs[0],report=jobs.find(j=>j.state==='succeeded'&&typeof j.output?.summary==='string'&&j.output.summary.trim());
 const profile=state.company?.profile||{},complete=!!(profile.description?.trim()&&profile.audience?.trim()),connected=state.integrations?.some(i=>i.id==='openai'&&i.configured);
 const active=jobs.some(j=>activeStates.has(j.state)),uncertain=last?.state==='uncertain';
 const available=complete&&connected&&!active&&!uncertain;
 const list=(title,items)=>Array.isArray(items)&&items.some(v=>typeof v==='string'&&v.trim())?'<h3>'+title+'</h3><ul>'+items.filter(v=>typeof v==='string'&&v.trim()).map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul>':'';
 const reportHtml=report?'<details class="operation-details" open><summary>Diagnóstico salvo · '+esc(formatTime(report.updatedAt))+'</summary><div class="prose"><h3>Leitura da empresa</h3><p>'+esc(report.output.summary)+'</p>'+list('Recomendações',report.output.recommendations)+list('Perguntas para aprofundar',report.output.questions)+'</div></details>':'<p>Nenhum diagnóstico concluído ainda. Salve o que sua empresa oferece e quem ela atende para iniciar a análise.</p>';
 const blocked=!complete?'<p><a href="#/brand">Complete e salve o negócio e o público em Marca.</a></p>':!connected?'<p><a href="#/integrations">Conecte a inteligência para iniciar a análise.</a></p>':uncertain?'<p>Confira a tentativa anterior no histórico antes de solicitar outra análise.</p>':'';
 return '<section class="panel form-panel" data-company-diagnosis aria-label="Diagnóstico da empresa"><div class="form-section-heading"><span>✧</span><div><h2>Diagnóstico da empresa</h2><p>Uma leitura do seu negócio, posicionamento e prioridades a partir das informações salvas.</p></div></div><p class="micro-copy">Análise do cadastro e do conhecimento fornecido. Não inclui pesquisa externa de mercado. As recomendações não alteram automaticamente os fatos da marca.</p>'+(last?'<div class="job-detail-meta"><strong>'+esc(statuses[last.state]||'Estado a conferir')+'</strong><span>Última solicitação · '+esc(formatTime(last.createdAt||last.updatedAt))+'</span><button type="button" class="p-button ghost" data-action="job-detail" data-id="'+esc(last.id)+'">Ver execução</button></div>':'')+(last?.error?'<p class="notice-box">'+esc(last.error)+'</p>':'')+reportHtml+blocked+'<div class="detail-actions"><button type="button" class="p-button secondary" data-action="company-diagnosis" '+(available?'':'disabled')+'>'+(active?'Análise em andamento':report?'Atualizar diagnóstico':'Gerar diagnóstico')+'</button><a class="subtle-link" href="#/brand">Revisar informações da marca ↗</a></div><p class="micro-copy">Gerar o diagnóstico usa IA e o perfil salvo. Salvar o cadastro não inicia uma execução. Após alterar o cadastro, salve e gere novamente para atualizar a análise.</p></section>';
}
